import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEvo,validEvo,advanceEvo,numericEvo,nextGeneration}from './evo-models.js?v=20261023-physicscomplete01';import{showEvo}from './evo-visuals.js?v=20261023-physicscomplete01';export{showEvo};
export function mountEvo(l,p,root,{save,done,feedback}){let ts=tasksForEvo(l.widget.slice(4)),w=p.widget;w.evoTask??=ts[0].id;w.evoDrafts??={};w.evoPassed??=[];let i=ts.findIndex(t=>t.id===w.evoTask);if(i<0)i=0;let t=ts[i],v=w.evoDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEvo(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.evoPassed.includes(t.id));
syncProcessMovie(l,1,['trait-data','variation','selection-data','breeding-goals','breeding-evidence','engineering-uses','engineering-evidence','transfer-evidence'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('evoCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('evoAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEvo">Reveal evidence →</button><p id="evoReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEvo(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#evoReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEvo(c,v.answer);}
else if(t.type==='sequence'){body=field('evoNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEvo">Advance pathway →</button><p id="evoReadout" aria-live="polite"></p>';draw=()=>{showEvo(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#evoReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}
else if(t.type==='cohort'){v.habitat??='dark';v.generation??=0;v.counts??={light:10,dark:10};v.environments??=[];body='<p>Start 10 light/10 dark. Camouflage doubles relative contribution in this toy 20-offspring model. Changing habitat resets the starting cohort.</p>'+field('evoHabitat','Habitat',[['light','Light background'],['dark','Dark background']],v.habitat)+field('evoPrediction','Which inherited variant should become more common?',[['light','Light variant'],['dark','Dark variant']],v.prediction)+'<button class="secondary" id="advanceCohort">Advance generation →</button><p id="cohortReadout" aria-live="polite"></p>';draw=()=>{showEvo('selection-data',{counts:v.counts,habitat:v.habitat,generation:v.generation,title:t.title});$('#cohortReadout').textContent='Generation '+v.generation+': light '+v.counts.light+', dark '+v.counts.dark+'. Recorded habitats: '+(v.environments.join(', ')||'none');};valid=()=>v.generation>=2&&v.prediction===v.habitat;}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="evoNumber">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="evoNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('evoReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEvo(t.kind,{title:t.title,...(t.kind==='selection-data'?{counts:{light:8,dark:12},generation:'fresh',caption:'Fresh evidence: find the dark-variant percentage'}:{}),label:'Original illustrative evidence'});valid=()=>numericEvo(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="evoEvidence"></p><div class="lab-actions"><button class="secondary" id="recordEvo">Record reasoning</button><button class="secondary" id="nextEvo">Next challenge →</button></div><p id="evoProgress"></p>';
const status=()=>{$('#evoEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.evoPassed.includes(t.id)?'Challenge recorded.':'';if(t.type==='cohort')$('#evoEvidence').textContent='Recorded habitats: '+v.environments.join(', ');$('#evoProgress').textContent=ts.filter(t=>w.evoPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='evoCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='evoHabitat'){if(!val)return;v.habitat=val;v.generation=0;v.counts={light:10,dark:10};v.prediction='';save();remount();return;}if(id==='evoPrediction')v.prediction=val;else if(id==='evoAnswer')v.answer=val;else if(id==='evoNext')v.next=val;else if(id==='evoNumber')v.number=val;else if(id==='evoReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v.number=e.target.value;save();};}
if($('#advanceCohort'))$('#advanceCohort').onclick=()=>{if(!v.prediction){feedback('Make a prediction first.',true);return;}if(v.generation>=3){feedback('Record this habitat, then compare the other one.');return;}v.counts=nextGeneration(v.counts,v.habitat);v.generation++;save();draw();feedback(v.prediction===v.habitat?'The population proportion changes; individuals keep their inherited variant.':'Compare the new proportions with your prediction.',v.prediction!==v.habitat);};
if($('#revealEvo'))$('#revealEvo').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEvo(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEvo(t.cases[v.case],v.answer));};
if($('#advanceEvo'))$('#advanceEvo').onclick=()=>{let n=advanceEvo(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEvo').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='cohort'&&!v.environments.includes(v.habitat))v.environments.push(v.habitat);if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type==='cohort'?v.environments.length===2:t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.evoPassed.includes(t.id))w.evoPassed.push(t.id);p.widgetDone=ts.every(t=>w.evoPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextEvo').onclick=()=>{if(!w.evoPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.evoTask=ts[(i+1)%ts.length].id;save();remount();};}
